SELECT
    T0."CardCode",
    T0."CardName",
    T0."Phone1",
    T0."E_Mail",
    T2."Descr"                 AS "Tipo",
    T1."Street"
FROM OCRD T0
LEFT JOIN (
    SELECT
        "CardCode",
        "Street",
        ROW_NUMBER() OVER (
            PARTITION BY "CardCode"
            ORDER BY CASE WHEN "AdresType" = 'B' THEN 0 ELSE 1 END, "Address"
        ) AS "rn"
    FROM CRD1
    WHERE UPPER(TRIM("Address")) = 'MATRIZ'
) T1 ON T1."CardCode" = T0."CardCode" AND T1."rn" = 1
LEFT JOIN UFD1 T2
       ON T2."TableID" = 'OCRD'
      AND T2."FieldID" = (SELECT "FieldID" FROM CUFD
                          WHERE "TableID" = 'OCRD' AND "AliasID" = 'SYP_TCONTRIB')
      AND T2."FldValue" = T0."U_SYP_TCONTRIB"
WHERE T0."CardType" = 'S'
  AND T0."CardCode" IN (
    'P0993400257001', 'P1307049807001', 'P0990013438001', 'P0924561160001', 'P0919462168001',
    'P0993370397001', 'P0926268376001', 'P0909122665001', 'P0991298657001', 'P0992611170001',
